function(container, apiUrl, tables) {
  // テーブルインデックスマッピング
  const tableMap = {};
  tables.forEach((t, idx) => {
    tableMap[t.tableName] = idx;
  });

  const monthInput = container.querySelector('[data-testid="analysis-month-filter"]');
  const today = new Date();
  const currentMonth = `${today.getFullYear()}-${String(today.getMonth() + 1).padStart(2, '0')}`;
  monthInput.value = currentMonth;

  // ===== データ取得関数 =====
  async function loadData() {
    try {
      // 各テーブルのデータを取得
      const contracts = await window.aivicApi.list(tableMap['ライセンス契約']) || [];
      const assignments = await window.aivicApi.list(tableMap['ユーザーライセンス割当']) || [];
      const utilization = await window.aivicApi.list(tableMap['ライセンス利用率分析']) || [];
      const editions = await window.aivicApi.list(tableMap['エディション']) || [];
      const features = await window.aivicApi.list(tableMap['機能']) || [];
      const featureLogs = await window.aivicApi.list(tableMap['機能利用ログ']) || [];

      // 選択月でフィルタ
      const selectedMonth = monthInput.value;
      const filteredUtil = utilization.filter(u => u.分析対象年月 === selectedMonth);

      // ===== KPI 計算 =====
      const totalLicenses = contracts.reduce((sum, c) => sum + (c.ライセンス数 || 0), 0);
      const assignedLicenses = assignments.filter(a => a.ステータス === '有効').length;
      const avgUtilization = filteredUtil.length > 0
        ? Math.round(filteredUtil.reduce((sum, u) => sum + (u.利用率パーセンテージ || 0), 0) / filteredUtil.length)
        : 0;
      const monthlyCost = filteredUtil.length > 0
        ? Math.round(filteredUtil.reduce((sum, u) => sum + (u.推定月額費用 || 0), 0) / filteredUtil.length)
        : 0;

      container.querySelector('[data-testid="kpi-total-licenses"]').textContent = totalLicenses.toLocaleString();
      container.querySelector('[data-testid="kpi-assigned-licenses"]').textContent = assignedLicenses.toLocaleString();
      container.querySelector('[data-testid="kpi-utilization-rate"]').textContent = avgUtilization;
      container.querySelector('[data-testid="kpi-monthly-cost"]').textContent = monthlyCost.toLocaleString();

      // ===== チャート 1: エディション別ライセンス分布 =====
      const editionLicenses = {};
      contracts.forEach(c => {
        const edName = c.ライセンスタイプ || '不明';
        editionLicenses[edName] = (editionLicenses[edName] || 0) + (c.ライセンス数 || 0);
      });
      const edLabels = Object.keys(editionLicenses);
      const edData = Object.values(editionLicenses);
      const colors = ['#00a1de', '#0088b8', '#00d4aa', '#ffa500', '#ff6b6b', '#4ecdc4'];
      if (window.Chart && edLabels.length > 0) {
        const ctx1 = container.querySelector('#chart-edition-distribution').getContext('2d');
        new window.Chart(ctx1, {
          type: 'doughnut',
          data: {
            labels: edLabels,
            datasets: [{
              data: edData,
              backgroundColor: colors.slice(0, edLabels.length),
              borderColor: '#ffffff',
              borderWidth: 2
            }]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              legend: { position: 'bottom', labels: { font: { size: 11 }, color: '#16325c' } }
            }
          }
        });
      }

      // ===== チャート 2: エディション別利用率 =====
      const editionUtilMap = {};
      filteredUtil.forEach(u => {
        const edId = u.エディションID;
        const ed = editions.find(e => e.エディションID === edId);
        const edName = ed ? ed.エディション名 : '不明';
        if (!editionUtilMap[edName]) editionUtilMap[edName] = [];
        editionUtilMap[edName].push(u.利用率パーセンテージ || 0);
      });
      const edUtilLabels = Object.keys(editionUtilMap);
      const edUtilData = edUtilLabels.map(ed => {
        const vals = editionUtilMap[ed];
        return Math.round(vals.reduce((a, b) => a + b, 0) / vals.length);
      });
      if (window.Chart && edUtilLabels.length > 0) {
        const ctx2 = container.querySelector('#chart-edition-utilization').getContext('2d');
        new window.Chart(ctx2, {
          type: 'bar',
          data: {
            labels: edUtilLabels,
            datasets: [{
              label: '利用率 (%)',
              data: edUtilData,
              backgroundColor: '#00a1de',
              borderColor: '#0088b8',
              borderWidth: 1
            }]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            indexAxis: 'y',
            plugins: { legend: { display: false } },
            scales: {
              x: { beginAtZero: true, max: 100, ticks: { color: '#576d7b', font: { size: 10 } }, grid: { color: '#d9e1e6' } },
              y: { ticks: { color: '#16325c', font: { size: 11 } }, grid: { display: false } }
            }
          }
        });
      }

      // ===== チャート 3: 月別費用推移 =====
      const monthlyData = {};
      utilization.forEach(u => {
        const month = u.分析対象年月;
        if (month) {
          monthlyData[month] = (monthlyData[month] || 0) + (u.推定月額費用 || 0);
        }
      });
      const sortedMonths = Object.keys(monthlyData).sort();
      const costTrend = sortedMonths.map(m => monthlyData[m]);
      if (window.Chart && sortedMonths.length > 0) {
        const ctx3 = container.querySelector('#chart-monthly-cost-trend').getContext('2d');
        new window.Chart(ctx3, {
          type: 'line',
          data: {
            labels: sortedMonths,
            datasets: [{
              label: '推定月額費用 (円)',
              data: costTrend,
              borderColor: '#00a1de',
              backgroundColor: 'rgba(0, 161, 222, 0.1)',
              borderWidth: 2,
              fill: true,
              tension: 0.4,
              pointBackgroundColor: '#00a1de',
              pointBorderColor: '#ffffff',
              pointBorderWidth: 2,
              pointRadius: 4
            }]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: { legend: { display: false } },
            scales: {
              y: { beginAtZero: true, ticks: { color: '#576d7b', font: { size: 10 } }, grid: { color: '#d9e1e6' } },
              x: { ticks: { color: '#576d7b', font: { size: 10 } }, grid: { display: false } }
            }
          }
        });
      }

      // ===== チャート 4: 契約ステータス分布 =====
      const statusCount = {};
      contracts.forEach(c => {
        const st = c.契約ステータス || '不明';
        statusCount[st] = (statusCount[st] || 0) + 1;
      });
      const stLabels = Object.keys(statusCount);
      const stData = Object.values(statusCount);
      if (window.Chart && stLabels.length > 0) {
        const ctx4 = container.querySelector('#chart-contract-status').getContext('2d');
        new window.Chart(ctx4, {
          type: 'pie',
          data: {
            labels: stLabels,
            datasets: [{
              data: stData,
              backgroundColor: colors.slice(0, stLabels.length),
              borderColor: '#ffffff',
              borderWidth: 2
            }]
          },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              legend: { position: 'bottom', labels: { font: { size: 11 }, color: '#16325c' } }
            }
          }
        });
      }

      // ===== 契約一覧テーブル =====
      const contractTbody = container.querySelector('#contract-tbody');
      contractTbody.innerHTML = '';
      contracts.slice(0, 8).forEach(c => {
        const row = document.createElement('tr');
        row.style.borderBottom = '1px solid var(--border)';
        row.innerHTML = `
          <td style="padding: 8px; color: var(--text);">${c.契約名 || '-'}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${c.ライセンス数 || 0}</td>
          <td style="padding: 8px; text-align: center; color: var(--text); font-size: 11px; font-weight: 500;">
            <span style="background: ${c.契約ステータス === '有効' ? '#d4edda' : '#f8d7da'}; color: ${c.契約ステータス === '有効' ? '#155724' : '#721c24'}; padding: 2px 6px; border-radius: 3px;">
              ${c.契約ステータス || '-'}
            </span>
          </td>
          <td style="padding: 8px; text-align: right; color: var(--text);">¥${(c.年間費用 || 0).toLocaleString()}</td>
        `;
        contractTbody.appendChild(row);
      });
      if (contracts.length === 0) {
        contractTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      }

      // ===== 未使用ライセンス一覧 =====
      const unusedTbody = container.querySelector('#unused-tbody');
      unusedTbody.innerHTML = '';
      const unusedByEd = {};
      filteredUtil.forEach(u => {
        const edId = u.エディションID;
        const ed = editions.find(e => e.エディションID === edId);
        const edName = ed ? ed.エディション名 : '不明';
        if (!unusedByEd[edName]) unusedByEd[edName] = 0;
        unusedByEd[edName] += (u.未使用ライセンス数 || 0);
      });
      Object.entries(unusedByEd).forEach(([edName, unused]) => {
        const total = editionLicenses[edName] || 1;
        const pct = Math.round((unused / total) * 100);
        const row = document.createElement('tr');
        row.style.borderBottom = '1px solid var(--border)';
        row.innerHTML = `
          <td style="padding: 8px; color: var(--text);">${edName}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${unused}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${pct}%</td>
        `;
        unusedTbody.appendChild(row);
      });
      if (Object.keys(unusedByEd).length === 0) {
        unusedTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="3" style="padding: 12px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      }

      // ===== 機能利用ランキング =====
      const featureUsage = {};
      const featureUserCount = {};
      featureLogs.forEach(log => {
        const fId = log.機能ID;
        const f = features.find(f => f.機能ID === fId);
        const fName = f ? f.機能名 : '不明';
        const fCat = f ? f.カテゴリ : '-';
        const key = `${fName}|${fCat}`;
        if (!featureUsage[key]) {
          featureUsage[key] = 0;
          featureUserCount[key] = new Set();
        }
        featureUsage[key] += (log.利用回数 || 1);
        featureUserCount[key].add(log.ユーザーID);
      });
      const featureRanking = Object.entries(featureUsage)
        .map(([key, count]) => {
          const [fName, fCat] = key.split('|');
          return { name: fName, category: fCat, count, userCount: featureUserCount[key].size };
        })
        .sort((a, b) => b.count - a.count)
        .slice(0, 10);

      const featureRankTbody = container.querySelector('#feature-ranking-tbody');
      featureRankTbody.innerHTML = '';
      featureRanking.forEach(f => {
        const row = document.createElement('tr');
        row.style.borderBottom = '1px solid var(--border)';
        row.innerHTML = `
          <td style="padding: 8px; color: var(--text);">${f.name}</td>
          <td style="padding: 8px; text-align: center; color: var(--text-muted); font-size: 11px;">${f.category}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${f.count}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${f.userCount}</td>
        `;
        featureRankTbody.appendChild(row);
      });
      if (featureRanking.length === 0) {
        featureRankTbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="4" style="padding: 12px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
      }

    } catch (err) {
      console.error('Dashboard load error:', err);
    }
  }

  // ===== イベントリスナー =====
  monthInput.addEventListener('change', loadData);

  // 初期ロード
  loadData();
}
